example:
agent Counter {
    key id: String
    store n: Cell[Int]

    on call get() -> Effect[Int] { … }

    transition up:                        // ✗ after a handler
        new.n >= old.n
}

agent Counter {
    key id: String
    store n: Cell[Int]

    transition up:                        // ✓ before the handlers
        new.n >= old.n

    on call get() -> Effect[Int] { … }
}
